\label{prop:int:radius-model}
Positive rational numbers $(r_0,r_1,r_2,r_3)$ arise from a unique strict
rational-distance point if and only if
\begin{align}
 r_0^2+r_3^2&=r_1^2+r_2^2,\label{eq:int:flag}\\
 (1+r_0^2-r_1^2)^2+(1+r_0^2-r_2^2)^2&=4r_0^2,\label{eq:int:radiusquartic}\\
 -1<r_0^2-r_1^2&<1,\qquad
 -1<r_0^2-r_2^2<1.\label{eq:int:strict-radii}
\end{align}
The point is given by \eqref{eq:int:recover}.

\label{lem:int:symmetry}
A strict rational-distance point lies on neither a midline nor a
diagonal of the square. Its four radii are pairwise distinct.

\label{thm:int:pair-denominators}
For any distinct $i,j$, let $d_+$ and $d_-$ be the denominators of
$r_i+r_j$ and $r_i-r_j$. Then
\begin{equation}\label{eq:int:denominator-product}
 \gcd(d_+,d_-)=G,\qquad d_+d_-=L/2.
\end{equation}

\label{int:gaussian}
The integers $d_j$ are odd, pairwise coprime, and coprime to $L$.
Every prime dividing any $d_j$ is $1$ or $7$ modulo $8$. There are
nonzero $q_j\in\Z[i]$ such that
\begin{equation}\label{eq:int:gaussian-roots}
 U_j=m_jq_j^2,\qquad \Nm(q_j)=A_j/m_j>0.
\end{equation}
In particular $m_0,m_1,m_2,m_3$ are positive odd squarefree integers
with disjoint supports, and, for $z=x+iy$,
\begin{equation}\label{eq:int:gaussian-classes}
 [z-c_j]=[Lm_j]\quad\text{in }\Q(i)^*/\Q(i)^{*2}.
\end{equation}
Conversely, if a rational strict point has a primitive representation
with $X$ odd and admits \eqref{eq:int:gaussian-roots} with positive
integers $m_j$ and $q_j\in\Z[i]$, all four of its distances are rational.

\label{thm:int:prime-comparisons}
Let $K=2^{v_2(L)}$. Then
\begin{equation}\label{eq:int:two-bound}
 K^2<\frac{2+\sqrt2}{4}\,L.
\end{equation}
If $p$ is an odd prime with $p\mid L$ and $p\mid XY$, and
$P_p=p^{v_p(L)}$, then
\begin{equation}\label{eq:int:odd-bound}
 P_p^2<\frac{2+\sqrt2}{2p}\,L.
\end{equation}
In particular
\begin{equation}\label{eq:int:three-bound}
 3^{2v_3(L)}<\frac{2+\sqrt2}{6}\,L.
\end{equation}

\label{cor:int:six-smooth}
The least coordinate denominator of a strict rational-distance point
has a prime divisor at least $5$.

\label{lem:ell-diagonal-exclusion}
Neither diagonal of the square contains a strict rational four-distance
point.  The square symmetries let us choose the chamber
\begin{equation}\label{eq:ell-chamber}
 x+y>1,\qquad x>y.
\end{equation}

\label{thm:ell-exact-source}
Strict rational points in the chamber \eqref{eq:ell-chamber} are in
bijection with the union, over positive squarefree $n$, of the rational
solutions of \eqref{eq:ell-ordered-roots} for which
\begin{equation}\label{eq:ell-source-signs}
 -n<a<0<c-n,\qquad b,\ell,u,v,h>0,
\end{equation}
and
\begin{equation}\label{eq:ell-strict-metric}
 \frac{2u}{a+c}\left(-\frac ba+\frac\ell c\right)<2.
\end{equation}
For this correspondence the final square is
\begin{equation}\label{eq:ell-final-square}
 f(Q,R):=\frac{a+c}{2(c+n)}
       =\frac{1}{(r_0+r_3)^2}.
\end{equation}

\label{prop:ell-opposite-genus}
For every rational $0<c_0<2$, the smooth projective curve determined
by \eqref{eq:ell-fixed-opposite} is geometrically connected of genus five.

\label{prop:ell-adjacent-genus}
For every rational $c_0>0$ with $c_0\ne1$, this normalized cover
is geometrically connected of genus five.

\label{lem:common-ramified}
Let $p$ be odd and suppose $v_p(d)>0$ is odd.  If
$\mathcal U_t(\Q_p)$ is nonempty, then $\leg2p=1$ and every point satisfies
\begin{equation}\label{eq:common-ramified-classes}
 [\ell]_{\Q_p}\in\{1,[d]_{\Q_p}\}.
\end{equation}
If $\leg2p=1$, both classes in \eqref{eq:common-ramified-classes}
occur.

\label{prop:common-matrix}
Suppose
\begin{equation}\label{eq:common-delta-hyp}
 \Delta\equiv1\pmod8,\qquad p_i\equiv1\text{ or }7\pmod8,
 \qquad t>1,\qquad d\in\Delta\Q^{\times2}.
\end{equation}
Every rational point of $\mathcal U_t$ has
\begin{equation}\label{eq:common-kernel}
 [\ell]=\left[2\prod_{i=1}^r p_i^{e_i}\right],
 \qquad (e_1,\ldots,e_r)^\mathsf T\in\ker A_\Delta.
\end{equation}
If $\rank A_\Delta=r-1$, then
\begin{equation}\label{eq:common-two-classes}
 [\ell]\in\{[2],[2\Delta]\}.
\end{equation}

\label{thm:profile-six-pair-support}
Let $p$ be an odd prime dividing $V_{ij}$.  Then
\begin{equation}\label{eq:profile-six-pair-support}
 p\nmid s_{ij},\qquad \leg{-s_{ij}}p=1.
\end{equation}
Equivalently, every odd prime divisor of $V_{ij}$ is unramified and
split in $\Q(\sqrt{-s_{ij}})$.

\label{lem:profile-ramified-character}
For $p\mid m_i$ and $j\ne i$,
\begin{equation}\label{eq:profile-ramified-character}
 \leg{V_{ij}}p=\leg{m_j}p\,\sigma(p)^{d_{ij}-1}.
\end{equation}

\label{thm:profile-master}
For every pair $i\ne j$, let $e\in\{0,1\}$ satisfy
$e\equiv e_i+e_j\pmod2$.  Then
\begin{equation}\label{eq:profile-master}
 \mathcal G(V_{ij})^{1+e}
   =(-1)^{e_ie_j}\sigma(m_im_j)^{d_{ij}-1}.
\end{equation}

\label{thm:profile-main}
For every strictly interior point with four positive rational distances,
the canonical corner colours in \eqref{eq:profile-colours} satisfy
\begin{equation}\label{eq:profile-main}
 \boxed{\quad m_0m_3\equiv1\text{ or }15\pmod{16},\qquad
               m_1m_2\equiv1\text{ or }15\pmod{16}.\quad}
\end{equation}
More precisely, an opposite product with an even number of prime factors
congruent to $7$ modulo $8$ is $1$ modulo $16$; one with an odd number
is $15$ modulo $16$.

\label{thm:hp-uniform}
Suppose \eqref{eq:hp-domain} holds.  If $\operatorname{Loc}(p)$ holds
and $\mathcal T(p)=1$, then $C_p(\Q)=\varnothing$.

\label{cor:cs-15569-layer}
For a strict interior rational-distance configuration, put
$t=r_{00}r_{11}+r_{10}r_{01}$.  Then $\sf(t^2-1)\ne15569$.

\label{prop:theta-strict-lift}
A rational point $[\xi:\eta:1]\in D(\Q)$ is the image of a point of
$\mathcal U\cap C(\Q)$ if and only if
\begin{equation}
 \xi>0,\qquad\eta>0,\qquad
 v=\sqrt{\frac{\xi^2+\eta^2-2}{2}}\in\Q_{>0},\qquad
 \left|\frac{\xi^2-\eta^2}{28v}\right|<\frac7{11}.
 \label{eq:theta-strict-lift}
\end{equation}
For this choice of $v$, the unique point on the positive branch is
\begin{equation}
 P=\frac1v,\qquad Q=\frac\xi v,\qquad R=\frac\eta v,
 \qquad z=\frac wv,
 \qquad w=\frac{\xi^2-\eta^2}{28v}.
 \label{eq:theta-inverse}
\end{equation}

\label{thm:theta-lines}
The twenty-eight bitangents of $D$ are precisely the following lines:
\begin{enumerate}
\item $Z=uX$ and $Z=uY$, where $u=\epsilon r/2$ or $u=5\epsilon r$;
\item $Z=(\epsilon hX+\eta hY)/14$, where $h=9$ or $h=11$;
\item $Z=s(\epsilon hX+\eta jY)/102$, where
      $(h,j)=(9,11)$ or $(11,9)$;
\item $X=tY$, where $t=\epsilon r(s+7\eta)/2$.
\end{enumerate}
Each has two distinct contact points.  The associated odd-theta
\emph{\'etale} algebra is
\begin{equation}
 L_{\mathrm{odd}}
 =\Q^8\times\Q(\sqrt2)^4\times\Q(\sqrt{51})^4
          \times\Q(\sqrt2,\sqrt{51}).
 \label{eq:theta-algebra}
\end{equation}
The full Galois action is induced by the independent sign changes of $r$
and $s$ in the displayed lines.

\label{prop:crit-double}
The map \(\widetilde{\mathcal C}_\iota\to\mathcal C_\iota\) is a
geometrically connected unramified double cover of genus-one curves
with rational points. For \(p\equiv1\pmod4\), its number of
rational points above \(b=0\) is
\[
 B_p=\begin{cases}16,&p\equiv1\pmod8,\\8,&p\equiv5\pmod8.
 \end{cases}
\]
Moreover,
\begin{equation}\label{crit:double-count}
 \#\{V\in\mathcal C_\iota(\F_p):b(V)\ne0,\ \chi_p(2f(V))=1\}
 =\frac{\#E(\F_p)-B_p}{2}.
\end{equation}
The character is unchanged by rescaling projective coordinates.

\label{thm:nine-isogeny}
For every $t\in\Q\setminus\{0,1,-1\}$ there is an isogeny over $\Q$
\begin{equation}\label{eq:nine-isogeny}
 \Jac(D_t)\sim_{\Q}
 E_d^2\times G_t\times F_+^2\times F_-^2\times H_+\times H_-.
\end{equation}
The rank of the group of rational N\'eron--Severi classes of $\Jac(D_t)$
is at least twelve.

\label{lem:nine-flex}
If $y^2=x(x-A)(x-B)$ is nonsingular and has a rational point of order
three, then there is $k\in\Q\setminus\{0,1,-1,-\tfrac12,-2\}$ such that
\begin{equation}\label{eq:nine-flex}
 \frac BA=\frac{1+2k}{(1-k)(1+k)^3}.
\end{equation}
There is also a nonzero rational $r$ with $A=r^2(1-k^2)$.

\label{lem:nine-three-torsion}
For rational $t\notin\{0,1,-1\}$, the curve $G_t$ has no rational
three-torsion.  For $t>1$ the following additional assertions hold:
\begin{enumerate}
\item if $T$ is a rational square, neither $H_+$ nor $F_-$ has
rational three-torsion;
\item if $T$ is twice a rational square, $F_+$ has no rational
three-torsion.
\end{enumerate}

\label{thm:nine-positive-ranks}
Let a strict rational-distance point have product parameter
$t=r_0r_3+r_1r_2$, and let the curves be as in
\eqref{eq:nine-elliptic-models}.  Each of
$E_d,G_t,F_+,F_-,H_+,H_-$ has positive rational rank.  In particular,
\begin{equation}\label{eq:nine-rank-nine}
 \rank\Jac(D_t)(\Q)\ge9.
\end{equation}

\label{thm:nine-rank-strata}
For the product parameter of any strict rational-distance point, the
following lower bounds hold:
\begin{equation}\label{eq:nine-rank-table}
\begin{array}{l|ccc|c}
 \text{condition}&\rank E_d&\rank F_+&\rank F_-&\rank\Jac(D_t)\\\hline
 T\notin\Q^{\times2}\cup2\Q^{\times2}&2&2&2&15\\
 T\in\Q^{\times2}&1&2&1&11\\
 T\in2\Q^{\times2},\ 2t\notin\Q^{\times2}&1&1&2&11\\
 T\in2\Q^{\times2},\ 2t\in\Q^{\times2}&1&1&1&9.
\end{array}
\end{equation}
Every entry in the table is a lower bound.

\label{lem:surface-real-boundary}
There is a point $P_*\in X(\Q)$ in the same real connected
component as every point of $\mathcal C$.
